{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943, a morpholine-substituted heteroaromatic kinase inhibitor with an aryl substituent, showed favorable brain uptake and specific binding in rodent autoradiography/PET studies; the query shares the morpholine-heteroaryl and aryl halide-like motif, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A fluorophenyl/morpholine heteroaromatic radioligand reached 2.8 SUV in rat brain within 5 minutes and was judged brain penetrant, supporting the brain-penetrant potential of the query's morpholinopyridine-containing core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine with a dichlorophenyl group, showed brain-plasma ratios >1 after oral dosing in mice; the query contains the same 2-aminopyrimidine and haloaryl pharmacophore, supporting meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-containing aminoquinazoline analogue showed a brain/plasma ratio of 2.4 in a rat pharmacodynamic model, demonstrating that morpholine-substituted heteroaromatic kinase inhibitors can achieve high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A morpholine-containing analogue with an additional amide-pyrrolidine substituent had a brain-blood ratio of 0.07, but the query lacks this polar amide/pyrrolidine bulk, reducing the transferability of this poor-penetration result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "CLR457, which combines morpholine and aminopyrimidine features, showed minimal CNS penetration (brain/plasma AUC 0.07), but it also contains an oxazolidinone and trifluoromethyl group absent in the query, so this contradictory signal is only partially transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query combines morpholine-heteroaryl and 2-aminopyrimidine/haloaryl features present in multiple direct brain-penetrant analogues, while the poor-penetration analogues carry additional polar or highly lipophilic liabilities not present in the query.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain concentration measurement for the query molecule.",
    "No P-glycoprotein/BCRP efflux data for the query.",
    "Morgan similarities to evidence molecules are only moderate (0.24-0.30), limiting quantitative transfer.",
    "Evidence comes from different species and assay formats (PET, autoradiography, PK, PD models)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

